 boolean accept(JSONObject s){android.content.SharedPreferences p=getSharedPreferences("filters",0);String label=(s.optString("name")+" "+s.optString("title")).toLowerCase(Locale.ROOT);String include=p.getString("include","").trim().toLowerCase(Locale.ROOT),exclude=p.getString("exclude","").trim().toLowerCase(Locale.ROOT);for(String word:include.split(","))if(!word.trim().isEmpty()&&!label.contains(word.trim()))return false;for(String word:exclude.split(","))if(!word.trim().isEmpty()&&label.contains(word.trim()))return false;float max=p.getFloat("gb",0);long bytes=s.optJSONObject("behaviorHints")==null?0:s.optJSONObject("behaviorHints").optLong("videoSize",0);if(bytes==0){java.util.regex.Matcher m=java.util.regex.Pattern.compile("([0-9]+(?:\\.[0-9]+)?)\\s*(gb|gib|mb|mib)").matcher(label);if(m.find())bytes=(long)(Double.parseDouble(m.group(1))*(m.group(2).startsWith("g")?1073741824d:1048576d));}return max<=0||bytes==0||bytes<=max*1073741824d;}
